package org.apache.commons.lang3.time;

import java.io.*;
import java.math.*;
import java.text.ParseException;
import java.text.ParsePosition;
import java.text.SimpleDateFormat;
import java.util.*;
import java.util.Calendar;
import java.util.Date;
import java.util.GregorianCalendar;
import java.util.Iterator;
import java.util.NoSuchElementException;
import java.util.TimeZone;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class DateUtils_isSameLocalTime_TriageGen2Test {

    @Test
    public void testIsSameLocalTime_NullCal1_ThrowsException() {
        try {
            DateUtils.isSameLocalTime(null, Calendar.getInstance());
            Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_NullCal2_ThrowsException() {
        try {
            DateUtils.isSameLocalTime(Calendar.getInstance(), null);
            Assert.fail("Expected IllegalArgumentException");
        } catch (IllegalArgumentException e) {
            Assert.assertEquals("The date must not be null", e.getMessage());
        }
    }

    @Test
    public void testIsSameLocalTime_IdenticalCalendars_ReturnsTrue() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        // Ensure they are exactly the same
        cal2.setTimeInMillis(cal1.getTimeInMillis());

        Assert.assertTrue(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMillisecond_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.MILLISECOND, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentSecond_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.SECOND, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentMinute_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.MINUTE, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentHour_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.HOUR, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentDayOfYear_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.DAY_OF_YEAR, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentYear_ReturnsFalse() {
        Calendar cal1 = Calendar.getInstance();
        Calendar cal2 = Calendar.getInstance();
        cal2.add(Calendar.YEAR, 1);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentEra_ReturnsFalse() {
        // Creating BC dates to test ERA
        Calendar cal1 = new GregorianCalendar(Calendar.BC, 1, 1, 12, 0, 0);
        Calendar cal2 = new GregorianCalendar(Calendar.AD, 1, 1, 12, 0, 0);

        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }

    @Test
    public void testIsSameLocalTime_DifferentClasses_ReturnsFalse() {
        // Using GregorianCalendar vs a different implementation or mock if possible, 
        // but since Calendar.getInstance() usually returns GregorianCalendar, 
        // we can use a subclass.
        Calendar cal1 = new GregorianCalendar();
        Calendar cal2 = new Calendar() {
            @Override
            public int get(int field) { return 0; }
            @Override
            public long getTimeInMillis() { return cal1.getTimeInMillis(); }
            @Override
            public void timeInMillis(long millis) {}
            @Override
            public void addTime(int amount) {}
            @Override
            public void addTime(int amount, int field) {}
            @Override
            public void getTime(Calendar field) {}
            @Override
            public void getTime(Calendar field, Calendar field2) {}
            @Override
            public void set(int field, int value) {}
            @Override
            public void set(int field, int value, int value2) {}
            @Override
            public void set(int field, int value, int value2, int value3) {}
            @Override
            public void setLenient(boolean leniency) {}
            @Override
            public boolean isLenient() { return true; }
            @Override
            public void clear() {}
            @Override
            public void clear(int field) {}
            @Override
            public void clear(int field, int value) {}
            @Override
            public void roll(int field, int amount) {}
            @Override
            public void add(int field, int amount) {}
            @Override
            public void unset(int field) {}
            @Override
            public void unset(int field, int value) {}
            @Override
            public int compareTo(Calendar o) { return 0; }
            @Override
            public String toString() { return "MockCalendar"; }
        };

        // Manually set fields to match cal1 for the logic check, 
        // but class comparison should fail.
        // However, the method checks class first in the logical AND chain.
        // Since we want to test the class check specifically:
        Assert.assertFalse(DateUtils.isSameLocalTime(cal1, cal2));
    }
}
